<?php $abierto = !in_array($t['estado'], ['resuelto', 'cerrado']); $pasos = ['abierto' => 'Recibido', 'en_proceso' => 'En atención', 'resuelto' => 'Resuelto', 'cerrado' => 'Cerrado']; $idx = array_search($t['estado'] === 'pendiente' ? 'en_proceso' : $t['estado'], array_keys($pasos)); ?>
<div class="page-head"><div><div class="crumbs"><a href="<?= url('portal') ?>">Inicio</a> / <a href="<?= url('portal/tickets') ?>">Mis tickets</a> / <?= e($t['codigo']) ?></div><h1><?= e($t['asunto']) ?></h1><p><?= e($t['codigo']) ?> · <?= e($t['categoria']) ?> · <?= estado_pill($t['estado']) ?> <?= prio_pill($t['prioridad']) ?></p></div></div>
<div class="card-ui mb-3"><div class="stepper"><?php $i = 0; foreach ($pasos as $k => $l): $cur = $i === $idx; $done = $i < $idx; ?><div class="step <?= $cur ? 'cur' : ($done ? 'done' : '') ?>"><span><?= $done ? '<i class="bi bi-check-lg"></i>' : $i + 1 ?></span><b><?= $l ?></b></div><?php $i++; endforeach; ?></div>
  <?php if ($t['estado'] === 'pendiente'): ?><div class="alert alert-warning small mt-3 mb-0">Estamos esperando información o una acción de tu parte. Respóndenos abajo.</div><?php endif; ?></div>
<div class="row g-3"><div class="col-lg-8">
  <div class="card-ui mb-3"><div class="card-head"><div><h6>Descripción</h6></div></div><p class="mb-0" style="white-space:pre-line"><?= e($t['descripcion'] ?: 'Sin detalle.') ?></p></div>
  <div class="card-ui"><div class="card-head"><div><h6>Conversación con soporte</h6></div></div>
    <?php foreach ($com as $m): $mio = (int)$m['usuario_id'] === (int)$u['id']; ?><div class="d-flex gap-2 mb-3 <?= $mio ? 'flex-row-reverse' : '' ?>"><?= avatar_html($m['autor'] ?: 'Soporte', $m['color'] ?: '#4f46e5', 'avatar-sm') ?><div style="max-width:80%"><div class="small text-muted <?= $mio ? 'text-end' : '' ?>"><b><?= $mio ? 'Tú' : e($m['autor'] ?: 'Soporte') ?></b> · <?= fdate($m['created_at'], 'd/m H:i') ?></div><div class="p-2 px-3 rounded-3 mt-1" style="background:<?= $mio ? 'var(--brand-soft)' : 'var(--bg)' ?>;white-space:pre-line"><?= e($m['comentario']) ?></div></div></div><?php endforeach; if (!$com): ?><p class="text-muted small">Todavía no hay mensajes. Puedes escribirnos aquí.</p><?php endif; ?>
    <?php if ($t['estado'] !== 'cerrado'): ?><form method="post" action="<?= url('portal/comentar/' . $t['id']) ?>" class="form-ui mt-3"><?= csrf_field() ?><textarea class="form-control mb-2" name="comentario" rows="3" maxlength="3000" placeholder="<?= $abierto ? 'Escribe un mensaje a soporte…' : 'Si el problema continúa, escríbenos y reabriremos el ticket' ?>" required></textarea><button class="btn btn-brand btn-sm"><i class="bi bi-send me-1"></i><?= $abierto ? 'Enviar mensaje' : 'Reabrir con un mensaje' ?></button></form><?php endif; ?></div></div>
  <div class="col-lg-4"><div class="card-ui"><div class="info-list">
    <div class="info-item"><span>Creado</span><b><?= fdate($t['created_at'], 'd/m/Y H:i') ?></b></div>
    <div class="info-item"><span>Atención estimada</span><b><?= $abierto ? fdate($t['fecha_limite'], 'd/m/Y H:i') : '—' ?></b></div>
    <?php if ($t['resuelto_at']): ?><div class="info-item"><span>Resuelto</span><b><?= fdate($t['resuelto_at'], 'd/m/Y H:i') ?></b></div><?php endif; ?>
    <div class="info-item"><span>Técnico</span><b><?= e($t['tecnico'] ?: 'Por asignar') ?></b></div>
    <?php if ($t['act_codigo']): ?><div class="info-item"><span>Equipo</span><b><?= e($t['act_codigo'] . ' · ' . $t['act_tipo']) ?></b></div><?php endif; ?></div></div></div></div>
